def _validate_positive_int(raw: str, flag: str) -> int | None:
    if not raw or not raw.isdigit():
        print(f"Error: {flag} value must be a positive integer, got '{raw}'", file=sys.stderr)
        return None
    value = int(raw, 10)
    if value < 1:
